props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"A strong faith that by Kṛṣṇa consciousness one will be elevated to the highest perfection of life is called \",[\"$\",\"em\",\"1\",{\"children\":\"vyavasāyātmikā\"}],\" intelligence. The \",[\"$\",\"$L20\",\"3\",{\"href\":\"/en/library/cc/madhya/22/62/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Caitanya-caritāmṛta\"}],\" (\",[\"$\",\"em\",\"2\",{\"children\":\"Madhya\"}],\" 22.62)\"]}],\" states:\"]}]}],[\"$\",\"$L29\",\"child-757\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-center italic\",\"dangerouslySetInnerHTML\":{\"__html\":\"‘śraddhā’-śabde – viśvāsa kahe sudṛḍha niścaya
kṛṣṇe bhakti kaile sarva-karma kṛta haya\"}}]}],[\"$\",\"$L29\",\"child-758\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:2\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Faith means unflinching trust in something sublime. When one is engaged in the duties of Kṛṣṇa consciousness, he need not act in relationship to the material world with obligations to family traditions, humanity or nationality. Fruitive activities are the engagements of one’s reactions from past good or bad deeds. When one is awake in Kṛṣṇa consciousness, he need no longer endeavor for good results in his activities. When one is situated in Kṛṣṇa consciousness, all activities are on the absolute plane, for they are no longer subject to dualities like good and bad. The highest perfection of Kṛṣṇa consciousness is renunciation of the material conception of life. This state is automatically achieved by progressive Kṛṣṇa consciousness.\"}}]}],[\"$\",\"$L29\",\"child-759\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:3\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"The resolute purpose of a person in Kṛṣṇa consciousness is based on knowledge. Vāsudevaḥ sarvam iti sa mahātmā su-durlabhaḥ: a person in Kṛṣṇa consciousness is the rare good soul who knows perfectly that Vāsudeva, or Kṛṣṇa, is the root of all manifested causes. As by watering the root of a tree one automatically distributes water to the leaves and branches, so by acting in Kṛṣṇa consciousness one can render the highest service to everyone – namely self, family, society, country, humanity, etc. If Kṛṣṇa is satisfied by one’s actions, then everyone will be satisfied.\"}}]}],[\"$\",\"$L29\",\"child-760\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:4\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"Service in Kṛṣṇa consciousness is, however, best practiced under the able guidance of a spiritual master who is a bona fide representative of Kṛṣṇa, who knows the nature of the student and who can guide him to act in Kṛṣṇa consciousness. As such, to be well versed in Kṛṣṇa consciousness one has to act firmly and obey the representative of Kṛṣṇa, and one should accept the instruction of the bona fide spiritual master as one’s mission in life. Śrīla Viśvanātha Cakravartī Ṭhākura instructs us, in his famous prayers for the spiritual master, as follows:\"}}]}],[\"$\",\"$L29\",\"child-761\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:5\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-center italic\",\"dangerouslySetInnerHTML\":{\"__html\":\"yasya prasādād bhagavat-prasādo
yasyāprasādān na gatiḥ kuto ’pi
dhyāyan stuvaṁs tasya yaśas tri-sandhyaṁ
